    "reply": "Tôi cần biết tên nhân viên cụ thể bạn muốn kiểm tra trong nhóm Sales."
}

{
    "calls": [
        {
            "name": "clarify",
            "args": {
                "question": "Bạn muốn xác nhận và tạo ticket cho lỗi VPN LT-204 với mức ưu tiên cao? Có đúng là bạn muốn đổi mức ưu tiên từ medium thành high không?",
                "response_type": "yes_no"
            }
        }
    ],
    "reply": "Xin lỗi, tôi cần xác nhận lại để đảm bảo thông tin chính xác và phù hợp với yêu cầu của bạn."
}

{
    "calls": [
        {
            "name": "clarify",
            "args": {
                "question": "Bạn có thể cung cấp ID tài khoản cụ thể (ví dụ: EMP-1007) không?",
                "response_type": "yes_no"
            }
        },
        {
            "name": "clarify",
            "args": {
                "question": "Bạn có thể cung cấp ID thiết bị cụ thể (ví dụ: DT-087) không?",
                "response_type": "yes_no"
            }
        },
        {
            "name": "clarify",
            "args": {
                "question": "Bạn muốn kiểm tra security của thiết bị này trong môi trường nào (production hoặc staging)?",
